questions.question:
What does this print?
int i, s = 0;
for (i = 1; i <= 10; i++) { if (i % 3 == 0) continue; s += i; }
printf("%d", s);

What is printed?
void f(int x) { x = 10; }
int main() { int a = 5; f(a); printf("%d", a); }

What is printed?
void f(int *x) { *x = 10; }
int main() { int a = 5; f(&a); printf("%d", a); }

Consider:
int x = 1;
void f() { printf("%d", x); }
void g() { int x = 2; f(); }
main calls g(). What is printed under static scoping and under dynamic scoping?

What does this print?
char s[] = "abcdef"; int i;
for (i = 0; s[i]; i += 2) putchar(s[i]);

What does this print?
int a[5] = {5, 1, 4, 2, 3}, i, m = a[0];
for (i = 1; i < 5; i++) if (a[i] > m) m = a[i];
printf("%d", m);

What does this print?
int a[] = {10, 20, 30}; int *p = a;
printf("%d ", *p++); printf("%d", *p);

What does this print?
int a[] = {10, 20, 30}; int *p = a;
(*p)++; printf("%d %d", a[0], *p);

What does this print?
int a[5] = {1, 2, 3, 4, 5}, *p, s = 0;
for (p = a; p < a + 5; p++) s += *p;
printf("%d", s);

What does this print?
void swap(int *x, int *y) { int t = *x; *x = *y; *y = t; }
int main() { int a = 1, b = 2; swap(&a, &b); printf("%d %d", a, b); }

What does this print?
int x = 10; int *p = &x; int **q = &p;
printf("%d", **q + *p);
